"""Real injected Monitoring HTML with backend-generated synthetic attendance; no Google writes."""
import json,subprocess,os
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[2];REPO=ROOT.parents[1]
script=r"""import {sessionHarness,plain} from './apps-script/absensi-dashboard/tests/support/sesi-harness.mjs';const h=sessionHarness();h.t.h.patch('Kehadiran','KHD001','id_kehadiran',{status_kehadiran:'lengkap'});for(let i=10;i<=31;i++){h.append('Peserta',{id_peserta:'PST'+i,nama_pegawai:'Peserta Uji '+i});h.append('Keikutsertaan',{id_keikutsertaan:'KST'+i,id_peserta:'PST'+i,id_program:'PRG001',id_jenjang:'JEN001',status_keikutsertaan:'terdaftar',unit_kerja_saat_pelatihan:'Unit '+i});}for(const [i,status] of ['hadir','terlambat','sakit','izin','alpa'].entries())h.call(h.staff,'simpanPresensiManualIndex',{id_sesi:'SES001',id_keikutsertaan:'KST'+(i+10),versi:'',status,keterangan:'Catatan manual',id_permintaan:'browser_initial_manual_000'+i});const responses={};for(const name of ['muatAwalIndex','muatKehadiranIndex','muatRekapJPProgramIndex','muatNilaiPerilakuProgramIndex','muatCatatanPerilakuIndex','muatDaftarIzinIndex','muatDaftarVerifikasiSesiPanitia','muatPengajuanKoreksiPanitia'])responses[name]=h.call(h.staff,name,...(name==='muatAwalIndex'||name.includes('VerifikasiSesiPanitia')||name.includes('Pengajuan')?[]:name.includes('ProgramIndex')?['PRG001']:['SES001']));process.stdout.write(JSON.stringify(plain({html:h.t.c.keluaranAplikasiPanitia_('Index','Monitoring').content,identity:h.t.c.muatSesiAplikasiPanitia(h.staff.token),login:h.staff,key:h.staff.storage_key,responses})));"""
f=json.loads(subprocess.check_output(['node','--input-type=module','-e',script],cwd=REPO,text=True))
mock=r'''
window.F=FIXTURE;window.calls=[];window.hold=false;window.fail=false;window.pending=[];
sessionStorage.setItem(F.key,F.login.token);
function result(name,arg){if(name==='muatSesiAplikasiPanitia')return F.identity;if(name==='panggilBacaanDashboardPanitia')return {sukses:true,hasil:arg.permintaan.map(p=>({sukses:true,data:result('panggilAplikasiPanitia',{nama:p.nama,args:p.args})}))};if(name!=='panggilAplikasiPanitia')throw Error('Unexpected '+name);if(arg.nama==='simpanPresensiManualIndex'){if(window.fail){window.fail=false;throw Error('Koneksi terputus');}const d=arg.args[0],p=F.responses.muatKehadiranIndex.peserta.find(p=>p.id_keikutsertaan===d.id_keikutsertaan);p.manual={status:d.status,label:({hadir:'Hadir',terlambat:'Terlambat',sakit:'Sakit',izin:'Izin',alpa:'Alpa'})[d.status],hadir:['hadir','terlambat'].includes(d.status),terlambat:d.status==='terlambat',keterangan:d.keterangan};p.status=p.manual.hadir?'lengkap':d.status;p.tidak_hadir=!p.manual.hadir;p.id_kehadiran='HDR-browser';p.versi='saved-version';return {sukses:true,pesan:'Presensi manual tersimpan.'};}if(F.responses[arg.nama])return JSON.parse(JSON.stringify(F.responses[arg.nama]));throw Error('Missing fixture '+arg.nama);}
function bridge(ok,bad){return new Proxy({}, {get(t,name){if(name==='withSuccessHandler')return fn=>bridge(fn,bad);if(name==='withFailureHandler')return fn=>bridge(ok,fn);return arg=>{calls.push({name,arg:JSON.parse(JSON.stringify(arg??null))});const work=()=>{try{ok?.(result(name,arg));}catch(e){bad?.(e);}};if(name==='panggilAplikasiPanitia'&&arg.nama==='simpanPresensiManualIndex'&&window.hold)pending.push(work);else setTimeout(work,10);};}});}
window.google={script:{run:bridge(),history:{replace(){}},url:{getLocation(fn){fn({parameter:{page:'monitoring',program:'PRG001',jenjang:'JEN001',sesi:'SES001'}});}},host:{close(){}}}};
'''.replace('FIXTURE',json.dumps(f))
out=Path(os.environ.get('MANUAL_SCREENSHOT_DIR','/tmp/presensi-manual-preview'));out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 def open_page(width):
  page=b.new_page(viewport={'width':width,'height':1050});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script(mock)
  page.route('**/*',lambda r:r.fulfill(status=200,content_type='text/html',body=f['html']) if r.request.resource_type=='document' else r.abort());page.goto('https://script.google.com/macros/s/COPY/exec?page=monitoring&program=PRG001&jenjang=JEN001&sesi=SES001');expect(page.locator('#total')).to_have_text('23');return page,errors
 page,errors=open_page(1440);expect(page.locator('#tableBody tr')).to_have_count(10);expect(page.locator('#recordedAbsent')).to_have_text('3');expect(page.locator('#incomplete')).to_have_text('0');expect(page.locator('#complete')).to_have_text('3');expect(page.locator('#attendancePrev')).to_be_disabled();expect(page.locator('#attendanceNext')).to_be_enabled()
 page.wait_for_timeout(100);calls=page.evaluate('calls.length');height=page.locator('.attendance-tablebox').evaluate('e=>e.getBoundingClientRect().height');page.locator('#attendanceNext').click();expect(page.locator('#tableBody tr')).to_have_count(10);expect(page.locator('#attendancePageInfo')).to_contain_text('11–20');page.locator('#attendanceNext').click();expect(page.locator('#tableBody tr')).to_have_count(3);expect(page.locator('#attendanceNext')).to_be_disabled();assert page.evaluate('calls.length')==calls;assert page.locator('.attendance-tablebox').evaluate('e=>e.getBoundingClientRect().height')==height
 page.locator('#search').fill('Uji 10');expect(page.locator('#tableBody tr')).to_have_count(1);expect(page.locator('#tableBody')).to_contain_text('Peserta Uji 10');expect(page.locator('#attendancePageInfo')).to_contain_text('Halaman 1 dari 1');page.locator('#search').fill('');page.locator('[data-attendance-filter="recordedAbsent"]').click();expect(page.locator('#tableBody tr')).to_have_count(3);expect(page.locator('#tableBody')).to_contain_text('Sakit');page.locator('[data-attendance-filter="absent"]').click();expect(page.locator('#tableBody tr')).to_have_count(10);page.locator('#attendanceNext').click();expect(page.locator('#tableBody tr')).to_have_count(7);assert page.evaluate('calls.length')==calls
 page.locator('[data-attendance-filter="all"]').click();page.locator('.attendance-tablebox').evaluate('e=>e.scrollTop=100');assert page.locator('.attendance-tablebox th').first.evaluate('e=>e.getBoundingClientRect().top')>=page.locator('.attendance-tablebox').evaluate('e=>e.getBoundingClientRect().top')-1
 page.locator('#quickManual').click();expect(page.locator('#manualDialog')).to_be_visible();page.locator('#manualSearch').fill('Uji 31');page.locator('#manualPerson').select_option('KST31');page.locator('#manualStatus').select_option('terlambat');page.locator('#manualReason').fill('Petugas mencatat keterlambatan');page.evaluate('window.hold=true;window.fail=true');page.locator('#manualSave').click();expect(page.locator('#manualSave')).to_be_disabled();expect(page.locator('#manualPerson')).to_be_disabled();expect(page.locator('#manualClose')).to_be_disabled();page.keyboard.press('Escape');expect(page.locator('#manualDialog')).to_be_visible();page.evaluate('window.hold=false;pending.splice(0).forEach(fn=>fn())');expect(page.locator('#manualMessage')).to_contain_text('Koneksi terputus');expect(page.locator('#manualStatus')).to_be_disabled();page.locator('#manualClose').click();page.locator('#quickManual').click();expect(page.locator('#manualReason')).to_have_value('Petugas mencatat keterlambatan');page.locator('#manualSave').click();expect(page.locator('#manualDialog')).not_to_be_visible();expect(page.locator('#total')).to_have_text('23');saved=page.evaluate("calls.filter(c=>c.arg?.nama==='simpanPresensiManualIndex').map(c=>c.arg.args[0])");assert len(saved)==2 and saved[0]==saved[1];page.locator('#search').fill('Uji 31');expect(page.locator('#tableBody')).to_contain_text('Terlambat · manual');expect(page.locator('#tableBody')).to_contain_text('Potongan JP tetap 15 menit');assert not errors,errors
 page.locator('#search').fill('');page.locator('#attendanceTools').scroll_into_view_if_needed();page.screenshot(path=str(out/'Monitoring-Presensi-Manual-Desktop.png'),full_page=True);page.close()
 mobile,errors=open_page(390);expect(mobile.locator('#tableBody tr')).to_have_count(10);assert mobile.evaluate('document.documentElement.scrollWidth<=innerWidth');assert mobile.locator('.attendance-tablebox').evaluate('e=>e.clientHeight')<=482;mobile.locator('#quickManual').click();expect(mobile.locator('#manualDialog')).to_be_visible();assert mobile.locator('#manualDialog').evaluate('e=>e.getBoundingClientRect().width')<=390;mobile.screenshot(path=str(out/'Presensi-Manual-Mobile.png'));mobile.locator('#manualClose').click();assert not errors,errors;b.close()
print('PASS: 23 synthetic participants, 10/page, cross-page search/status, no RPC on paging, fixed independent scroll/sticky headers, typed absence counts, manual draft/cancel/busy/same-ID retry and mobile; Google mocked.')
